CREATE TABLE [Users] ([UserID] COUNTER CONSTRAINT PK_Users PRIMARY KEY, [FullName] TEXT(100) NOT NULL, [Email] TEXT(254) NOT NULL, [PasswordHash] TEXT(255) NOT NULL, [Phone] TEXT(20) NOT NULL, [Address] MEMO, [City] TEXT(100), [Role] TEXT(20) NOT NULL, [Status] TEXT(20) NOT NULL, [CreatedDate] DATETIME NOT NULL, [CartVersion] LONG NOT NULL);
CREATE UNIQUE INDEX UX_Users_Email ON [Users] ([Email]);
CREATE TABLE [Categories] ([CategoryID] COUNTER CONSTRAINT PK_Categories PRIMARY KEY, [CategoryName] TEXT(100) NOT NULL, [Description] MEMO, [Status] TEXT(20) NOT NULL);
CREATE UNIQUE INDEX UX_Categories_Name ON [Categories] ([CategoryName]);
CREATE TABLE [Products] ([ProductID] COUNTER CONSTRAINT PK_Products PRIMARY KEY, [CategoryID] LONG NOT NULL, [ProductName] TEXT(150) NOT NULL, [Brand] TEXT(100), [Unit] TEXT(40) NOT NULL, [Price] CURRENCY NOT NULL, [StockQuantity] LONG NOT NULL, [Version] LONG NOT NULL, [ExpiryDate] DATETIME, [Description] MEMO, [ImagePath] TEXT(255), [Status] TEXT(20) NOT NULL, [CreatedDate] DATETIME NOT NULL, CONSTRAINT FK_Products_Category FOREIGN KEY ([CategoryID]) REFERENCES [Categories] ([CategoryID]));
CREATE TABLE [Cart] ([CartID] COUNTER CONSTRAINT PK_Cart PRIMARY KEY, [UserID] LONG NOT NULL, [ProductID] LONG NOT NULL, [Quantity] LONG NOT NULL, [AddedDate] DATETIME NOT NULL, CONSTRAINT FK_Cart_User FOREIGN KEY ([UserID]) REFERENCES [Users] ([UserID]), CONSTRAINT FK_Cart_Product FOREIGN KEY ([ProductID]) REFERENCES [Products] ([ProductID]));
CREATE UNIQUE INDEX UX_Cart_User_Product ON [Cart] ([UserID], [ProductID]);
CREATE TABLE [Orders] ([OrderID] COUNTER CONSTRAINT PK_Orders PRIMARY KEY, [UserID] LONG NOT NULL, [OrderDate] DATETIME NOT NULL, [TotalAmount] CURRENCY NOT NULL, [Status] TEXT(30) NOT NULL, [DeliveryAddress] MEMO NOT NULL, [City] TEXT(100) NOT NULL, [PaymentMethod] TEXT(30) NOT NULL, [CheckoutToken] TEXT(64) NOT NULL, CONSTRAINT FK_Orders_User FOREIGN KEY ([UserID]) REFERENCES [Users] ([UserID]));
CREATE UNIQUE INDEX UX_Orders_Token ON [Orders] ([CheckoutToken]);
CREATE INDEX IX_Orders_User ON [Orders] ([UserID]);
CREATE TABLE [OrderItems] ([OrderItemID] COUNTER CONSTRAINT PK_OrderItems PRIMARY KEY, [OrderID] LONG NOT NULL, [ProductID] LONG NOT NULL, [ProductName] TEXT(150) NOT NULL, [Unit] TEXT(40) NOT NULL, [Quantity] LONG NOT NULL, [Price] CURRENCY NOT NULL, [Subtotal] CURRENCY NOT NULL, CONSTRAINT FK_Items_Order FOREIGN KEY ([OrderID]) REFERENCES [Orders] ([OrderID]), CONSTRAINT FK_Items_Product FOREIGN KEY ([ProductID]) REFERENCES [Products] ([ProductID]));
CREATE INDEX IX_Items_Order ON [OrderItems] ([OrderID]);
